"""
Based on the questions in the RubricHub evaluation set, call the LLM API to generate answers and save them to a JSON file.

Output format:
{
    "idx_0": {
        "prompt": "original question text",
        "answer": "the answer generated by the model"
    },
    ...
}
"""

import argparse
import json
import logging
import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from threading import Lock
from typing import Dict, List

import numpy as np
import pandas as pd
from openai import OpenAI

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    stream=sys.stdout,
    force=True,
)
logger = logging.getLogger(__name__)

# Global lock for thread-safe writes to the results
_result_lock = Lock()


def clean_llm_output(text: str) -> str:
    """Clean the LLM output, removing the <think>...</think> internal processing markers and their content."""
    if not isinstance(text, str):
        return ""

    # Find the position of the </think> tag
    think_end_tag = "</think>"
    tag_index = text.find(think_end_tag)

    if tag_index != -1:
        # Extract the content after the tag and strip surrounding whitespace
        cleaned_text = text[tag_index + len(think_end_tag):].strip()
        return cleaned_text
    else:
        # If the tag is not found, return the original text (stripped of surrounding whitespace)
        return text.strip()


def extract_prompt_text(prompt_field) -> str:
    """
    Extract the question text from the prompt field.
    RubricHub's prompt field is a numpy ndarray of dicts, each dict has a 'content' key.
    Take the content of the first message.
    """
    if isinstance(prompt_field, np.ndarray) and len(prompt_field) > 0:
        first_msg = prompt_field[0]
        if isinstance(first_msg, dict) and "content" in first_msg:
            return first_msg["content"]
    # fallback: convert directly to a string
    return str(prompt_field)


def generate_answer(client: OpenAI, prompt_text: str, model: str, max_tokens: int) -> str:
    # print(prompt_text, flush=True)
    # print("="*20)
    """Call the LLM API to generate an answer."""
    response = client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt_text}],
        temperature=0.0,
        # max_tokens=max_tokens,
    )
    return clean_llm_output(response.choices[0].message.content)


def worker_process_chunk(
    api_base: str,
    api_key: str,
    model: str,
    chunk: List[dict],
    worker_id: int,
    max_tokens: int,
    result_dict: Dict,
) -> int:
    """
    Thread worker function: processes the data chunk assigned to this thread.
    Each element in chunk is {"idx": str, "prompt": str}.
    """
    client = OpenAI(base_url=api_base, api_key=api_key)
    success_count = 0

    for item in chunk:
        try:
            answer = generate_answer(client, item["prompt"], model, max_tokens)
            with _result_lock:
                result_dict[item["idx"]] = {
                    "prompt": item["prompt"],
                    "answer": answer,
                }
            success_count += 1
        except Exception as e:
            logger.error(f"[Worker-{worker_id}] failed to process item {item['idx']}: {e}")

        if success_count % 10 == 0:
            logger.info(
                f"[Worker-{worker_id}] processed {success_count}/{len(chunk)} items"
            )

    return success_count


def generate_responses(
    data_path: str,
    output_path: str,
    api_base: str,
    api_key: str,
    model: str,
    num_workers: int = 8,
    max_tokens: int = 4096,
):
    """
    Load the RubricHub evaluation set and generate answers using multithreaded parallel requests to the LLM API.

    Args:
        data_path: path to the RubricHub evaluation set parquet file
        output_path: path to the output answer-map JSON file
        api_base: LLM API address (e.g. http://127.0.0.1:8000/v1)
        api_key: API key
        model: model name
        num_workers: number of threads
        max_tokens: maximum number of tokens to generate per answer
    """
    # 1. Load the dataset
    logger.info(f"Loading dataset: {data_path}")
    df = pd.read_parquet(data_path)
    total = len(df)
    logger.info(f"Loaded {total} records")

    # 2. Extract prompts and build the task list
    items = []
    for idx, row in df.iterrows():
        prompt_text = extract_prompt_text(row["prompt"])
        items.append({"idx": f"idx_{idx}", "prompt": prompt_text})

    # 3. Evenly distribute across threads
    chunk_size = (total + num_workers - 1) // num_workers
    chunks = [items[i : i + chunk_size] for i in range(0, total, chunk_size)]
    logger.info(f"Starting {len(chunks)} threads, ~{chunk_size} items per thread")

    # 4. Multithreaded parallel requests
    shared_result: Dict = {}
    t_start = time.time()

    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        futures = {
            executor.submit(
                worker_process_chunk,
                api_base=api_base,
                api_key=api_key,
                model=model,
                chunk=chunk,
                worker_id=wid,
                max_tokens=max_tokens,
                result_dict=shared_result,
            ): wid
            for wid, chunk in enumerate(chunks)
        }

        for future in as_completed(futures):
            wid = futures[future]
            try:
                count = future.result()
                logger.info(f"[Worker-{wid}] done, successfully processed {count} items")
            except Exception as e:
                logger.error(f"[Worker-{wid}] thread execution error: {e}")

    elapsed = time.time() - t_start
    logger.info(
        f"All done, {len(shared_result)} items in {elapsed:.1f}s "
        f"({len(shared_result) / elapsed:.1f} items/s)"
    )

    # 5. Save the results
    os.makedirs(os.path.dirname(output_path) or ".", exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(shared_result, f, ensure_ascii=False, indent=2)

    logger.info(f"Answer mapping saved to: {output_path}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Generate RubricHub answers by calling the LLM API with multiple threads"
    )
    parser.add_argument(
        "--data",
        type=str,
        default="dataset/eval_set_Science_400.parquet",
        help="Path to the RubricHub evaluation set parquet file (default: dataset/eval_set_Science_400.parquet)",
    )
    parser.add_argument(
        "--output",
        type=str,
        default="output/responses.json",
        help="Path to the output answer-map JSON file (default: output/responses.json)",
    )
    parser.add_argument(
        "--api_base",
        type=str,
        required=True,
        help="LLM API address, e.g. http://127.0.0.1:8000/v1",
    )
    parser.add_argument(
        "--api_key",
        type=str,
        default="EMPTY",
        help="API key (default EMPTY)",
    )
    parser.add_argument(
        "--model",
        type=str,
        required=True,
        help="Model name",
    )
    parser.add_argument(
        "--num_workers",
        type=int,
        default=8,
        help="Number of concurrent threads (default 8)",
    )
    parser.add_argument(
        "--max_tokens",
        type=int,
        default=4096,
        help="Maximum tokens to generate per answer (default 4096)",
    )
    args = parser.parse_args()

    generate_responses(
        data_path=args.data,
        output_path=args.output,
        api_base=args.api_base,
        api_key=args.api_key,
        model=args.model,
        num_workers=args.num_workers,
        max_tokens=args.max_tokens,
    )
